import json

with open('/app/benchmark/source_data.json') as f:
    data = json.load(f)

fed = data['fed_funds_rate']['data']
debt = data['external_debt_to_gdp']['data']
depr = data['currency_depreciation']['data']
ratings = data['sovereign_rating_changes']['data']

def get_x_from_quarter(q_str):
    y, q = q_str.split('-Q')
    return int(y) + (int(q) * 3 - 1.5) / 12.0

def get_x_from_annual(year):
    return int(year) + 11.5 / 12.0  # Dec

def get_x_from_month(ym_str):
    if len(ym_str) == 4: # just year
        return int(ym_str) + 0.5
    y, m = map(int, ym_str.split('-'))
    return y + (m - 0.5) / 12.0

def map_x(dec_year, width):
    # 2021.0 to 2025.0
    return max(0, min(width, (dec_year - 2021.0) / 4.0 * width))

def map_y(val, min_v, max_v, height):
    return height - (val - min_v) / (max_v - min_v) * height

countries = ["Argentina", "Sri Lanka", "Ghana", "Turkey", "Pakistan", "Egypt", "South Africa", "Brazil"]

html = """<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<style>
@import url('https://fonts.googleapis.com/css2?family=Crimson+Pro:ital,wght@0,400;0,600;1,400&family=JetBrains+Mono:wght@400;500&display=swap');

:root {
  --bg: #faf7f5;
  --surface: #ffffff;
  --border: #e7e5e4;
  --text: #1c1917;
  --text-dim: #57534e;
  --fed-line: #d97706; /* amber */
  --fed-fill: rgba(217, 119, 6, 0.1);
  --debt: #0369a1; /* slate */
  --depr: #be123c; /* rose */
  --downgrade: #dc2626; /* red */
  --upgrade: #16a34a; /* green */
  --default: #000000; /* black */
}
body {
  font-family: "Crimson Pro", serif;
  background-color: var(--bg);
  color: var(--text);
  margin: 0;
  padding: 60px;
  width: 1400px;
  box-sizing: border-box;
}
.header { margin-bottom: 40px; }
h1 { font-size: 38px; font-weight: 600; margin: 0 0 12px 0; color: #000; }
.subtitle { font-family: "JetBrains Mono", monospace; font-size: 15px; color: var(--text-dim); margin: 0 0 20px 0; line-height: 1.5; max-width: 1000px; }
.legend { display: flex; gap: 24px; font-family: "JetBrains Mono", monospace; font-size: 12px; margin-bottom: 40px; align-items: center; }
.leg-item { display: flex; align-items: center; gap: 8px; }
.leg-box { width: 12px; height: 12px; border-radius: 2px; }
.grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 24px;
}
.panel {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: 8px;
  padding: 20px;
  box-shadow: 0 2px 8px rgba(0,0,0,0.03);
}
.p-head { margin-bottom: 12px; }
.c-name { font-size: 22px; font-weight: 600; margin: 0; }
.c-metrics { font-family: "JetBrains Mono", monospace; font-size: 12px; color: var(--text-dim); display: flex; gap: 12px; margin-top: 4px; }
.svg-container { width: 100%; position: relative; }
svg { width: 100%; height: auto; overflow: visible; }
.axis-line { stroke: var(--border); stroke-width: 1; }
.axis-text { font-family: "JetBrains Mono", monospace; font-size: 10px; fill: var(--text-dim); text-anchor: middle; }
.fed-steep { fill: rgba(217, 119, 6, 0.05); }
</style>
</head>
<body>
<div class="header">
  <h1>The Transmission of US Monetary Tightening to Emerging Markets (2021-2024)</h1>
  <div class="subtitle">
    As the US Federal Reserve aggressively hiked rates (shaded area), high-debt emerging economies faced severe local currency depreciation<br>and a cluster of sovereign credit rating downgrades, making the transmission of global financial conditions visibly traceable.
  </div>
  <div class="legend">
    <div class="leg-item"><div class="leg-box" style="background:var(--fed-fill); border:1px solid var(--fed-line)"></div> Fed Funds Rate</div>
    <div class="leg-item"><div class="leg-box" style="background:var(--debt)"></div> External Debt (% GDP)</div>
    <div class="leg-item"><div class="leg-box" style="background:var(--depr); border-radius:6px"></div> Currency Depr. (%)</div>
    <div class="leg-item"><span style="color:var(--downgrade); font-size:16px;">▼</span> Downgrade</div>
    <div class="leg-item"><span style="color:var(--default); font-size:16px;">✖</span> Default</div>
    <div class="leg-item"><span style="color:var(--upgrade); font-size:16px;">▲</span> Upgrade</div>
  </div>
</div>

<div class="grid">
"""

W, H = 280, 160

# Process Fed data for polygon
fed_points = [ (map_x(2021.0, W), map_y(0.25, 0, 6, H)) ] # start
for f in fed:
    dec = get_x_from_quarter(f['date'])
    x = map_x(dec, W)
    y = map_y(f['rate_pct'], 0, 6, H)
    fed_points.append((x, y))
fed_points.append((map_x(2025.0, W), map_y(fed[-1]['rate_pct'], 0, 6, H))) # end

path_d = f"M {fed_points[0][0]},{H} "
for px, py in fed_points:
    path_d += f"L {px},{py} "
path_d += f"L {fed_points[-1][0]},{H} Z"

# Add panels
for c in countries:
    c_debt = sorted([d for d in debt if d['country'] == c], key=lambda x: x['year'])
    c_depr = sorted([d for d in depr if d['country'] == c], key=lambda x: x['year'])
    c_rat = sorted([r for r in ratings if r['country'] == c], key=lambda x: x['date'])

    d2024 = c_debt[-1]['debt_gdp_pct'] if c_debt else 0
    dp2024 = c_depr[-1]['depreciation_pct'] if c_depr else 0

    html += f'<div class="panel"><div class="p-head"><h2 class="c-name">{c}</h2>'
    html += f'<div class="c-metrics"><span style="color:var(--debt)">Debt: {d2024}%</span> <span style="color:var(--depr)">Depr: {dp2024}%</span></div></div>'

    html += f'<div class="svg-container"><svg viewBox="0 0 {W} {H}">'

    # Grid lines
    html += f'<line x1="0" y1="{H}" x2="{W}" y2="{H}" class="axis-line" />'
    html += f'<line x1="0" y1="{H/2}" x2="{W}" y2="{H/2}" class="axis-line" stroke-dasharray="2,2" />'
    html += f'<line x1="0" y1="0" x2="{W}" y2="0" class="axis-line" stroke-dasharray="2,2" />'

    # Fed steep phase shading (2022 Q1 to 2023 Q3 roughly)
    steep_start = map_x(2022.0, W)
    steep_end = map_x(2023.75, W)
    html += f'<rect x="{steep_start}" y="0" width="{steep_end - steep_start}" height="{H}" class="fed-steep" />'

    # Fed Rate polygon
    html += f'<path d="{path_d}" fill="var(--fed-fill)" stroke="var(--fed-line)" stroke-width="1.5" />'

    # Debt Bars (bar encoding)
    bar_w = 12
    for d in c_debt:
        x = map_x(get_x_from_annual(d['year']) - 0.25, W)
        y = map_y(d['debt_gdp_pct'], 0, 100, H)
        h = H - y
        html += f'<rect x="{x - bar_w/2}" y="{y}" width="{bar_w}" height="{h}" fill="var(--debt)" opacity="0.8" rx="2" />'

    # Depr Line/Dots (dot encoding / line)
    depr_pts = []
    for d in c_depr:
        x = map_x(get_x_from_annual(d['year']), W)
        y = map_y(d['depreciation_pct'], 0, 100, H)
        depr_pts.append((x, y))

